    private static async Task<IResult> ExecuteMutationAsync(HttpContext http, Guid journalId, FinanceActionWriteRequest? request, ITrustedRequestContextResolver resolver, FinanceAuthorizationService auth, IFinancePersistence persistence, string operation, FinanceJournalStatus target, FinanceResourceType resourceType)
    {
        if (!TryIfMatch(http, out var version)) return Problem(400, "if_match_required", "A valid If-Match version is required.");
        return await ExecuteMutationAsync(http, resolver, auth, operation, null, (context, key) => persistence.TransitionJournalAsync(context, new FinanceJournalActionCommand(journalId, version, request?.Reason, key, Fingerprint(request) + Convert.ToBase64String(version)), target, http.RequestAborted), resourceType, journalId);
    }

    private static async Task<IResult> ExecuteMutationAsync(HttpContext http, Guid journalId, ITrustedRequestContextResolver resolver, FinanceAuthorizationService auth, IFinancePersistence persistence, FinanceResourceType resourceType)
    {
        if (!TryIfMatch(http, out var version)) return Problem(400, "if_match_required", "A valid If-Match version is required.");
        return await ExecuteMutationAsync(http, resolver, auth, "finance.journal.post", null, (context, key) => persistence.PostJournalAsync(context, new FinanceJournalActionCommand(journalId, version, null, key, Fingerprint(journalId) + Convert.ToBase64String(version)), http.RequestAborted), resourceType, journalId);
    }

    private static async Task<IResult> Read<T>(HttpContext http, ITrustedRequestContextResolver resolver, FinanceAuthorizationService authorization, string operation, Guid? companyId, Func<FinanceRequestContext, Task<T>> action, FinanceResourceType? resourceType = null, Guid? resourceId = null)
    {
        var resolved = await Resolve(http, resolver, authorization, operation, companyId, resourceType, resourceId); if (resolved.Error is not null) return resolved.Error; try { return Results.Ok(await action(resolved.Context!)); } catch (Exception) { return Problem(503, "finance_unavailable", "Finance data is temporarily unavailable."); }
    }

    private static async Task<IResult> ExecuteMutationAsync<T>(HttpContext http, ITrustedRequestContextResolver resolver, FinanceAuthorizationService authorization, string operation, Guid? companyId, Func<FinanceRequestContext, string, Task<FinanceOperationResult<T>>> action, FinanceResourceType? resourceType = null, Guid? resourceId = null)
    {
        try { await http.RequestServices.GetRequiredService<IAntiforgery>().ValidateRequestAsync(http); } catch (AntiforgeryValidationException) { return Problem(403, "antiforgery_failed", "The request could not be validated."); }
        var key = http.Request.Headers["Idempotency-Key"].FirstOrDefault(); if (!FoundationCorrelation.IsValid(key)) return Problem(400, "idempotency_key_invalid", "A valid Idempotency-Key is required.");
        var resolved = await Resolve(http, resolver, authorization, operation, companyId, resourceType, resourceId); if (resolved.Error is not null) return resolved.Error; FinanceOperationResult<T> result; try { result = await action(resolved.Context!, key!); } catch (Exception exception) when (IsFinanceConflict(exception)) { return Problem(409, "finance_conflict", "The Finance operation conflicted with another committed change."); } catch (Exception) { return Problem(503, "finance_unavailable", "Finance is temporarily unavailable."); }
        if (!result.Succeeded || result.Value is null) return Problem(StatusFor(result.Code), result.Code, "The Finance operation was not completed."); if (TryVersion(result.Value, out var version)) http.Response.Headers.ETag = $"\"{Convert.ToBase64String(version)}\""; return Results.Ok(result.Value);
    }

    private static async Task<(FinanceRequestContext? Context, IResult? Error)> Resolve(HttpContext http, ITrustedRequestContextResolver resolver, FinanceAuthorizationService authorization, string operation, Guid? companyId, FinanceResourceType? resourceType, Guid? resourceId)
    {
        var foundation = await resolver.ResolveAsync(http, http.RequestAborted); if (!FinanceRequestContext.TryCreate(foundation, out var context) || context is null) return (null, Problem(foundation.SecurityProfile == FoundationSecurityProfile.Anonymous ? 401 : 403, "access_denied", "The operation is not available for this security context."));
        var resolvedCompanyId = companyId;
        if (resourceType is { } type)
        {
            if (resourceId is not { } id || id == Guid.Empty) return (null, Problem(404, "finance_resource_not_found", "The requested Finance resource was not found."));
            resolvedCompanyId = await http.RequestServices.GetRequiredService<IFinancePersistence>().ResolveCompanyIdAsync(context, type, id, http.RequestAborted);
            if (resolvedCompanyId is null) return (null, Problem(404, "finance_resource_not_found", "The requested Finance resource was not found."));
        }
        var decision = authorization.Authorize(context, operation, resolvedCompanyId); return decision.Allowed ? (context, null) : (null, Problem(403, decision.Code, "The requested Finance scope is not authorized."));
    }

    private static FinanceJournalCommand ToCommand(FinanceJournalWriteRequest request, string key) => new(request.CompanyId, request.JournalDate, request.PostingDate, request.TransactionCurrencyCode, request.ExchangeRate, request.ExchangeRateId, request.ExchangeRateVersionId, request.ExchangeRateVersionNumber, "manual-journal.v1", "manual", null, null, null, request.Description, request.Lines.Select(line => new FinanceJournalLineCommand(line.AccountId, line.Debit, line.Credit, null, null, line.CostCenterId, line.Description)).ToArray(), Guid.NewGuid(), key, Fingerprint(request), FinanceJournalAmountAuthority.ManualTransactionCurrency, FinanceApprovalRequirement.Required);
    private static bool TryIfMatch(HttpContext http, out byte[] version) { version = []; var value = http.Request.Headers.IfMatch.FirstOrDefault()?.Trim('"'); if (string.IsNullOrWhiteSpace(value)) return false; try { version = Convert.FromBase64String(value); return version.Length > 0; } catch (FormatException) { return false; } }
    private static bool TryVersion<T>(T value, out byte[] version) { version = []; var property = typeof(T).GetProperty("Version"); if (property?.GetValue(value) is not byte[] candidate) return false; version = candidate; return true; }
    private static int StatusFor(string code) => code is "company_scope_denied" or "permission_denied" or "approval_policy_not_configured" ? 403 : code.Contains("not_found", StringComparison.OrdinalIgnoreCase) ? 404 : code is "concurrency_conflict" or "idempotency_conflict" or "source_effect_exists" ? 409 : 422;
    private static bool IsFinanceConflict(Exception exception) => exception.GetType().Name is "DbUpdateException" or "DbUpdateConcurrencyException" || exception.InnerException is not null && IsFinanceConflict(exception.InnerException);
    private static string Fingerprint<T>(T value) => FinanceFingerprint.For(typeof(T).Name, JsonSerializer.Serialize(value));
    private static IResult Problem(int status, string code, string detail) => Results.Problem(detail, statusCode: status, title: code, extensions: new Dictionary<string, object?> { ["code"] = code });

