    public sealed record FinanceCostCenterWriteRequest(Guid CompanyId, string Code, string EnglishName, string? ArabicName, DateOnly EffectiveFrom, DateOnly? EffectiveTo);
    public sealed record FinancePostingRuleWriteRequest(Guid CompanyId, string SourceContract, string SourceEvent, Guid DebitAccountId, Guid CreditAccountId, bool CostCenterRequired, DateOnly EffectiveFrom, DateOnly? EffectiveTo);
    public sealed record FinancePostingRuleLifecycleWriteRequest(Guid CompanyId, FinancePostingRuleLifecycle Lifecycle);
    public sealed record FinanceJournalLineWriteRequest(Guid AccountId, decimal Debit, decimal Credit, Guid? CostCenterId, string? Description);
    public sealed record FinanceJournalWriteRequest(Guid CompanyId, DateOnly JournalDate, DateOnly PostingDate, string? TransactionCurrencyCode, decimal? ExchangeRate, Guid? ExchangeRateId, Guid? ExchangeRateVersionId, int? ExchangeRateVersionNumber, string Description, IReadOnlyList<FinanceJournalLineWriteRequest> Lines);
    public sealed record FinanceActionWriteRequest(string? Reason);
    public sealed record FinanceReverseWriteRequest(DateOnly? PostingDate, string? Reason);
